  "supportive_card_ids": ["C01","C07","C10","C11","C20","C22","C32","C45","C50","C21","C52","C44","C130","C131","C149","C107","C143"],
  "contradictory_card_ids": ["C220","C223","C207","C216","C233","C250","C221","C253"],
  "prediction_basis_card_ids": ["C01","C07","C10","C11","C20","C22","C32","C45","C50","C21","C52","C44","C130","C131","C149","C107","C143"],
  "claims": [
    {
      "claim": "The query is a 17-acetoxy-20-keto 19-norsteroid with an 11β-(4-dimethylaminophenyl) substituent (ulipristal acetate-like); the closest transferable training contexts are orally bioavailable steroids: ethinylestradiol F 25-65% (C01), 17-methyltestosterone good oral bioavailability (C07), estetrol high and dose-related (C11), and a projected steroid F 40-70% (C10).",
      "card_ids": ["C01","C07","C10","C11"]
    },
    {
      "claim": "Quantitative steroid-context records are above the 20% threshold: estetrol F >=70% in female rats at 0.05 and 0.5 mg/kg and ~33% in mice (C20,C22,C32,C45,C50); 17-methyltestosterone relative F 97-101% in humans and absolute F 37% in rats (C21,C52,C44).",
      "card_ids": ["C20","C22","C32","C45","C50","C21","C52","C44"]
    },
    {
      "claim": "L4 intestinal absorption/permeability records for steroid analogs show high permeability and substantial absorption despite low solubility: megestrol acetate BCS class II/highly permeable (C130), chlormadinone acetate greater intestinal absorption than norethindrone (C131), progesterone 91% fraction absorbed (C149), dexamethasone 100% human fraction absorbed (C107), and prednisolone high human Peff (C143).",
      "card_ids": ["C130","C131","C149","C107","C143"]
    },
    {
      "claim": "L6 hepatic metabolism records for close 17-acetoxy-20-keto progestin analogs show extensive CYP3A4/UGT-mediated metabolism (medroxyprogesterone acetate HLM CLint 250 µL/min/mg and UGT1A9 CLint up to 378 µL/min/mg; megestrol acetate oxidized by CYP3A4/3A5 and described as completely metabolized in the liver), providing mechanistic evidence for possible first-pass loss, but these are analog, not query, measurements and do not establish F < 20%.",
      "card_ids": ["C220","C223","C207","C216","C233","C250","C221"]
    },
    {
      "claim": "Metabolism alone does not imply low F in this steroid series: ethinylestradiol has measurable hepatic glucuronidation (C237) yet human F is 25-65% (C01), and estetrol/17-methyltestosterone are orally bioavailable despite steroid metabolism.",
      "card_ids": ["C237","C01","C11","C07"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C220","C223","C207","C216","C233","C250","C221","C253"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability or matched oral-versus-IV exposure measurement for the query molecule is present in the supplied records.",
    "No query-specific hepatic clearance, metabolic stability, or CYP/UGT phenotyping data are supplied; L6 records are for steroid analogs, not the query.",
    "Dose and formulation are not specified, so dissolution-limited absorption cannot be quantified despite high logD and low predicted solubility.",
    "Ester hydrolysis of the 17-acetoxy group and metabolism of the 4-dimethylaminophenyl substituent are not experimentally characterized for the query.",
    "No IV reference for the query exists in the records, so absolute F cannot be directly calculated."
  ],
  "decision_summary": "Prediction remains high: the query is a 17-acetoxy-20-keto 19-norsteroid (ulipristal acetate-like), and the closest transferable steroid contexts (ethinylestradiol, estetrol, 17-methyltestosterone, projected steroid) all support F >= 20%, with quantitative values above 20%. L4 permeability records for steroid analogs support high permeability despite low solubility. L6 hepatic metabolism records for close progestin analogs (medroxyprogesterone acetate, megestrol acetate) provide mechanistic evidence of possible first-pass loss and lower confidence, but they are indirect and do not establish F < 20%; metabolized steroids such as ethinylestradiol still have F 25-65%. Therefore high is retained with low confidence."
}

